"""A tiny WordNet-style lexical graph: synsets, hypernym chains, inheritance and path similarity."""
SYNSETS = {
    "entity.n": ([], None), "animal.n": (["animal", "creature"], "entity.n"), "mammal.n": (["mammal"], "animal.n"),
    "bat.n.01": (["bat", "chiropteran"], "mammal.n"), "dog.n": (["dog", "domestic dog"], "mammal.n"),
    "artifact.n": (["artifact"], "entity.n"), "equipment.n": (["sports equipment"], "artifact.n"),
    "bat.n.02": (["bat", "cricket bat"], "equipment.n"), "vehicle.n": (["vehicle"], "artifact.n"),
    "car.n": (["car", "automobile", "auto"], "vehicle.n"), "suv.n": (["SUV"], "car.n"),
    "clever.a": (["intelligent", "clever", "bright", "brilliant", "smart"], None),
}
PART_OF = {"wheel": "car.n", "steering wheel": "car.n"}
ANTONYM = {"hot": "cold", "rich": "poor"}

def senses(word): return [s for s, (lemmas, _) in SYNSETS.items() if word in lemmas]
def chain(s):
    out = [s]
    while SYNSETS[out[-1]][1]: out.append(SYNSETS[out[-1]][1])
    return out

print("senses of 'bat':", senses("bat"))
for s in senses("bat"): print(f"  {s}: {' -> '.join(chain(s))}")
print("car is a hyponym of vehicle and a hypernym of SUV:", chain("suv.n")[:3])
print("synset for 'clever':", SYNSETS["clever.a"][0])
print("meronyms of car:", [p for p, w in PART_OF.items() if w == "car.n"], "| antonym of hot:", ANTONYM["hot"])

def path_sim(a, b):
    ca, cb = chain(a), chain(b)
    common = next(x for x in ca if x in cb)
    d = ca.index(common) + cb.index(common)
    return 1 / (1 + d), common
for a, b in [("bat.n.01", "dog.n"), ("bat.n.01", "bat.n.02"), ("car.n", "suv.n")]:
    sim, lcs = path_sim(a, b)
    print(f"path_similarity({a}, {b}) = {sim:.3f} (lowest common ancestor {lcs})")
print("inheritance: bat.n.01 is an animal?", "animal.n" in chain("bat.n.01"))

"""Four WSD methods on 'bank': most frequent sense, Naive Bayes, embedding similarity, and Lesk."""
import numpy as np, re

# 1. Most-frequent-sense baseline
counts = {"cricket bat": 80, "flying mammal": 20}
mfs = max(counts, key=counts.get)
print(f"MFS for 'bat': {mfs} (right {counts[mfs]/sum(counts.values()):.0%} of the time, never on 'the bat flew out of the cave')")

# 2. Naive Bayes with add-1 smoothing
V = ["loan", "approved", "money", "water", "fishing", "river"]
C = {"finance": [4, 2, 3, 0, 0, 1], "river": [0, 0, 0, 2, 1, 2]}
prior = {"finance": 0.8, "river": 0.2}
ctx = ["approved", "loan"]
for s in C:
    tot = sum(C[s]); score = prior[s]
    for w in ctx:
        p = (C[s][V.index(w)] + 1) / (tot + len(V)); score *= p
        print(f"  P({w}|{s}) = ({C[s][V.index(w)]}+1)/({tot}+{len(V)}) = {p:.4f}")
    print(f"score({s}) = {score:.4f}")
print("ratio finance/river ~", round((0.8 * 5/16 * 3/16) / (0.2 * 1/11 * 1/11)))

# 3. Embedding similarity (toy 2-d vectors standing in for sentence/gloss embeddings)
sent = np.array([1.2, 0.3])
gloss = {"financial institution that lends money": np.array([1.4, 0.7]), "sloping land beside a river": np.array([0.3, 1.1])}
cos = lambda a, b: a @ b / np.linalg.norm(a) / np.linalg.norm(b)
for g, v in gloss.items(): print(f"cos(sentence, '{g}') = {cos(sent, v):.2f}")

# 4. Simplified Lesk (overlap of context with gloss), with and without crude stemming
GLOSS = {"finance": "a financial institution that accepts deposits and provides loans and mortgages",
         "river": "sloping land beside a body of water the shore of a river"}
STOP = {"the", "a", "my", "of", "and", "that"}
stem = lambda w: re.sub(r"(s|es|ing|man)$", "", w)
def lesk(sentence, glosses, use_stem=False, prefix=False):
    norm = (lambda w: stem(w)) if use_stem else (lambda w: w)
    c = {norm(w) for w in sentence.lower().split() if w not in STOP}
    def match(a, b): return a == b or (prefix and min(len(a), len(b)) >= 4 and (a.startswith(b) or b.startswith(a)))
    return {s: sum(any(match(x, norm(w)) for x in c) for w in set(g.split()) - STOP) for s, g in glosses.items()}
print("Lesk 'The bank approved my loan':", lesk("The bank approved my loan", GLOSS), "(exact match)")
print("Lesk with stemming:", lesk("The bank approved my loan", GLOSS, True))
BASS = {"fish": "an edible fish of sea and fresh water", "music": "the lowest part in music played on a guitar or in a band"}
print("Lesk 'The fisherman caught a bass':", lesk("The fisherman caught a bass", BASS), "<- tie at 0")
print("with prefix matching (fisherman ~ fish):", lesk("The fisherman caught a bass", BASS, prefix=True))
